    AND business_code = #{businessCode}

choose.when:
SELECT * FROM metadata_field
WHERE table_code = #{tableCode}

    AND business_code = #{businessCode}

ORDER BY sort ASC, create_time ASC
LIMIT #{pageRequest.offset}, #{pageRequest.size}

choose.otherwise:
SELECT f.* FROM metadata_field f INNER JOIN metadata_table t ON f.table_code = t.table_code INNER JOIN metadata_business_system bs ON t.business_code = bs.business_code LEFT JOIN metadata_physical_database pdb ON ( NULLIF(TRIM(COALESCE(NULLIF(TRIM(t.database_name), ''), NULLIF(TRIM(bs.database_name), ''))), '') IS NOT NULL AND LOWER(TRIM(pdb.catalog_name)) = LOWER(TRIM(COALESCE(NULLIF(TRIM(t.database_name), ''), NULLIF(TRIM(bs.database_name), '')))) ) WHERE f.table_code = #{tableCode} AND bs.is_enabled = 1 AND t.is_enabled = 1 AND f.is_enabled = 1 AND (pdb.id IS NULL OR pdb.is_enabled = 1)
AND f.business_code = #{businessCode}
ORDER BY f.sort ASC, f.create_time ASC LIMIT #{pageRequest.offset}, #{pageRequest.size}

